        var events = new List<EffectEvent>();
        foreach (var e in evArr.EnumerateArray())
            events.Add(ParseEvent(e));

        Budget budget = Budget.None;
        if (root.TryGetProperty("budget", out var b) && b.ValueKind == JsonValueKind.Object)
            budget = ParseBudget(b);

        // 注：Budget 不直接存于 EffectScript（Audit 入参）。这里返回脚本；Budget 经 ToBudget 单独取。
        _ = budget;
        return new EffectScript(events.ToImmutableArray());
    }

    /// <summary>§4 — 从 JSON 取 Budget（caps 节）；缺省空预算。</summary>
    public static Budget ParseBudget(JsonElement b)
    {
        var caps = new Dictionary<ResourceId, NatStar>();
        if (b.TryGetProperty("caps", out var capsArr) && capsArr.ValueKind == JsonValueKind.Array)
        {
            foreach (var c in capsArr.EnumerateArray())
            {
                if (!c.TryGetProperty("resource", out var resEl) || !c.TryGetProperty("cap", out var capEl))
                    throw new ArgumentException("caps 项需 resource + cap", nameof(b));
                var r = ParseResource(resEl);
                var cap = capEl.ValueKind == JsonValueKind.Number ? NatStar.Of(capEl.GetUInt64()) : NatStar.Top;
                caps[r] = cap;
            }
        }
        return new Budget(caps);
    }

    private static EffectEvent ParseEvent(JsonElement e)
    {
        var life = ParseInterval(e.GetProperty("lifetime"));
        var scope = e.TryGetProperty("scope", out var s) ? ParseScope(s) : new ScopeId.Scene("Default");
        var loop = e.TryGetProperty("loop", out var l) && l.ValueKind == JsonValueKind.String
            ? LoopCount.Top
            : LoopCount.Of(l.ValueKind == JsonValueKind.Number ? l.GetUInt64() : 1);
        if (!e.TryGetProperty("footprint", out var fp) || fp.ValueKind != JsonValueKind.Array)
            throw new ArgumentException("event 必须有 footprint 数组", nameof(e));

        var claims = new List<Claim>();
        foreach (var c in fp.EnumerateArray())
            claims.Add(ParseClaim(c, scope));
        return new EffectEvent(life, scope, Signature.Of(claims.ToArray()), loop);
    }

    private static Interval ParseInterval(JsonElement v)
    {
        if (v.ValueKind == JsonValueKind.Number)
            return Interval.Exact(v.GetUInt64());
        if (v.ValueKind == JsonValueKind.Array)
        {
            var arr = v.EnumerateArray().ToImmutableArray();
            if (arr.Length != 2) throw new ArgumentException("interval 数组需 [lo,hi]", nameof(v));
            var lo = ParseBound(arr[0]);
            var hi = ParseBound(arr[1]);
            return new Interval(lo, hi);
        }
        throw new ArgumentException("interval 需是数或 [lo,hi]", nameof(v));
    }

    private static NatStar ParseBound(JsonElement b)
    {
        if (b.ValueKind == JsonValueKind.String) // "⊤" 或 "top" ⇒ 上界
            return NatStar.Top;
        if (b.ValueKind == JsonValueKind.Number)
            return NatStar.Of(b.GetUInt64());
        throw new ArgumentException("bound 需是数或 '⊤'", nameof(b));
    }

    private static Claim ParseClaim(JsonElement c, ScopeId scope)
    {
        var kind = Enum.Parse<Kind>(RequireString(c, "kind"), ignoreCase: true);
        var resource = ParseResource(c.GetProperty("resource"));
        var mode = Enum.Parse<Mode>(RequireString(c, "mode"), ignoreCase: true);
        var size = c.TryGetProperty("size", out var sz) ? ParseInterval(sz) : Interval.Default;
        return new Claim(kind, resource, mode, scope, size).Normalize();
    }

    private static ResourceId ParseResource(JsonElement r)
    {
        if (r.ValueKind != JsonValueKind.Object)
            throw new ArgumentException("resource 需是对象", nameof(r));
        foreach (var prop in r.EnumerateObject())
        {
            return prop.Name switch
            {
                "gpu" => new ResourceId.Gpu(new Rid(RequireString(prop.Value, "bufferId"))),
                "commandBuffer" => new ResourceId.CommandBuffer(RequireString(prop.Value, "channel", optional: true) ?? "gpu"),
                "memory" => new ResourceId.Memory(0),
                "tree" => new ResourceId.Tree(NodePathOrUnknown.Of(RequireString(prop.Value, "path", optional: true) ?? "root")),
                "self" => new ResourceId.Self(RequireString(prop.Value, "component", optional: true) ?? "self"),
                "physics" => new ResourceId.Physics(new Rid(RequireString(prop.Value, "bodyId", optional: true) ?? "b")),
                "disk" => new ResourceId.Disk(RequireString(prop.Value, "path", optional: true) ?? "disk")),
                "signal" => new ResourceId.Signal(new StringName(RequireString(prop.Value, "name", optional: true) ?? "sig")),
                "signalBus" or "signal_bus" => new ResourceId.SignalBus(new StringName(RequireString(prop.Value, "name", optional: true) ?? "bus")),
                "audioMixer" => new ResourceId.AudioMixer(0),
                "occupancy" => new ResourceId.Occupancy(RequireString(prop.Value, "channel", optional: true) ?? "ch"),
                "callback" => new ResourceId.Callback(RequireString(prop.Value, "id", optional: true) ?? "cb"),
                "network" => new ResourceId.Network(0, RequireString(prop.Value, "method", optional: true) ?? "m"),
                "input" => new ResourceId.Input(RequireString(prop.Value, "action", optional: true) ?? "a"),
                "custom" => new ResourceId.Custom(RequireString(prop.Value, "name", optional: true) ?? "x"),
                _ => throw new ArgumentException($"未知 resource 形状: {prop.Name}", nameof(r))
            };
        }
        throw new ArgumentException("resource 对象为空", nameof(r));
    }

    private static ScopeId ParseScope(JsonElement s)
    {
        if (s.ValueKind != JsonValueKind.Object)
            throw new ArgumentException("scope 需是对象", nameof(s));
        foreach (var prop in s.EnumerateObject())
        {
            return prop.Name switch
            {
                "scene" => new ScopeId.Scene(RequireString(prop.Value, "name", optional: true) ?? prop.Value.GetString() ?? "S"),
                "type" => new ScopeId.Type(RequireString(prop.Value, "name", optional: true) ?? prop.Value.GetString() ?? "T"),
                "method" => new ScopeId.Method(RequireString(prop.Value, "name", optional: true) ?? prop.Value.GetString() ?? "M"),
                "global" => new ScopeId.Global(),
                "shell" => new ScopeId.Shell(),
                "loop" => new ScopeId.Loop(RequireString(prop.Value, "id", optional: true) ?? prop.Value.GetString() ?? "L"),
                "conditional" => new ScopeId.Conditional(RequireString(prop.Value, "branch", optional: true) ?? prop.Value.GetString() ?? "C"),
                "async" => new ScopeId.Async(RequireString(prop.Value, "id", optional: true) ?? prop.Value.GetString() ?? "A"),
                _ => throw new ArgumentException($"未知 scope 形状: {prop.Name}", nameof(s))
            };
        }
        throw new ArgumentException("scope 对象为空", nameof(s));
    }

    private static string RequireString(JsonElement e, string field, bool optional = false)
    {
        if (!e.TryGetProperty(field, out var v))
        {
            if (optional) return null!;
            throw new ArgumentException($"缺字段 {field}", nameof(e));
        }
        if (v.ValueKind == JsonValueKind.String) return v.GetString()!;
        if (v.ValueKind == JsonValueKind.Object) return field; // 已在上层处理
        throw new ArgumentException($"字段 {field} 需是字符串", nameof(e));
    }
}
